"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PageHeader } from "@/components/app/page-header";
import { StatusBadge } from "@/components/app/status-badge";
import { EmptyState, LoadingState, ErrorState } from "@/components/app/empty-state";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Route, Search, MapPin, Calendar, ChevronRight, Plus, Truck } from "lucide-react";
import { formatDate } from "@/lib/constants";

export function PlanList() {
  const { navigate } = useAppStore();
  const [trips, setTrips] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState("");
  const [search, setSearch] = useState("");

  useEffect(() => {
    (async () => {
      try { const d = await apiGet("/trips"); setTrips(d.trips); }
      catch (e: any) { setError(e.message); }
      finally { setLoading(false); }
    })();
  }, []);

  if (loading) return <LoadingState />;
  if (error) return <ErrorState message={error} />;

  const filtered = trips.filter((t) => !search || (t.request?.competitionName || "").toLowerCase().includes(search.toLowerCase()));

  return (
    <div className="space-y-6">
      <PageHeader title="Lập kế hoạch lộ trình" description="Danh sách kế hoạch vận chuyển cần điều phối" icon={<Route className="h-5 w-5" />}
        actions={
          <div className="flex items-center gap-2">
            <div className="relative w-full sm:w-56"><Search className="absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" /><Input value={search} onChange={(e) => setSearch(e.target.value)} placeholder="Tìm kế hoạch..." className="pl-9" /></div>
          </div>
        }
      />
      {filtered.length === 0 ? (
        <EmptyState icon={<Route className="h-6 w-6" />} title="Chưa có kế hoạch" description="Đơn đã phê duyệt sẽ sẵn sàng để lập kế hoạch." />
      ) : (
        <div className="space-y-3">
          {filtered.map((t) => (
            <button key={t.planId} onClick={() => navigate("plan-detail", { id: t.planId })} className="flex w-full items-center gap-4 rounded-xl border border-border bg-card p-4 text-left transition-all hover:border-primary/40 hover:shadow-md">
              <div className="flex h-12 w-12 shrink-0 items-center justify-center rounded-xl bg-primary/10 text-primary"><Route className="h-6 w-6" /></div>
              <div className="min-w-0 flex-1">
                <p className="truncate text-sm font-semibold">{t.request?.competitionName || `Kế hoạch #${t.planId.slice(-8)}`}</p>
                <div className="mt-1 flex flex-wrap items-center gap-x-4 gap-y-1 text-xs text-muted-foreground">
                  <span className="flex items-center gap-1"><MapPin className="h-3 w-3" />{t.request?.origin?.name} → {t.request?.destination?.name}</span>
                  <span className="flex items-center gap-1"><Calendar className="h-3 w-3" />{formatDate(t.departureTime)}</span>
                  <span className="flex items-center gap-1"><Truck className="h-3 w-3" />{t.stops?.length || 0} chặng</span>
                </div>
              </div>
              <StatusBadge status={t.status} />
              <ChevronRight className="h-4 w-4 text-muted-foreground" />
            </button>
          ))}
        </div>
      )}
    </div>
  );
}
